/// Service for built-in functionality.
pub fn BuiltinService(comptime UserDataType: type, comptime ErrorSet: type) type {
    return struct {
        pub const package = "com.kcl.api";
        pub const service_name = "BuiltinService";

        /// Sends a ping request.
        Ping: *const fn (userdata: *UserDataType, request: PingArgs) ErrorSet!PingResult,
        /// Lists available methods.
        ListMethod: *const fn (userdata: *UserDataType, request: ListMethodArgs) ErrorSet!ListMethodResult,
    };
}

/// Service for KCL VM interactions.
pub fn KclService(comptime UserDataType: type, comptime ErrorSet: type) type {
    return struct {
        pub const package = "com.kcl.api";
        pub const service_name = "KclService";

        /// Ping KclService, return the same value as the parameter
        ///
        /// # Examples
        ///
        /// ```jsonrpc
        /// Request
        /// {
        /// "jsonrpc": "2.0",
        /// "method": "Ping",
        /// "params": {
        /// "value": "hello"
        /// },
        /// "id": 1
        /// }
        ///
        /// Response
        /// {
        /// "jsonrpc": "2.0",
        /// "result": {
        /// "value": "hello"
        /// },
        /// "id": 1
        /// }
        /// ```
        Ping: *const fn (userdata: *UserDataType, request: PingArgs) ErrorSet!PingResult,
        /// GetVersion KclService, return the kcl service version information
        ///
        /// # Examples
        ///
        /// ```jsonrpc
        /// Request
        /// {
        /// "jsonrpc": "2.0",
        /// "method": "GetVersion",
        /// "params": {},
        /// "id": 1
        /// }
        ///
        /// Response
        /// {
        /// "jsonrpc": "2.0",
        /// "result": {
        /// "version": "0.9.1",
        /// "checksum": "c020ab3eb4b9179219d6837a57f5d323",
        /// "git_sha": "1a9a72942fffc9f62cb8f1ae4e1d5ca32aa1f399",
        /// "version_info": "Version: 0.9.1-c020ab3eb4b9179219d6837a57f5d323\nPlatform: aarch64-apple-darwin\nGitCommit: 1a9a72942fffc9f62cb8f1ae4e1d5ca32aa1f399"
        /// },
        /// "id": 1
        /// }
        /// ```
        GetVersion: *const fn (userdata: *UserDataType, request: GetVersionArgs) ErrorSet!GetVersionResult,
        /// Parse KCL program with entry files.
        ///
        /// # Examples
        ///
        /// ```jsonrpc
        /// Request
        /// {
        /// "jsonrpc": "2.0",
        /// "method": "ParseProgram",
        /// "params": {
        /// "paths": ["./src/testdata/test.k"]
        /// },
        /// "id": 1
        /// }
        ///
        /// Response
        /// {
        /// "jsonrpc": "2.0",
        /// "result": {
        /// "ast_json": "{...}",
        /// "paths": ["./src/testdata/test.k"],
        /// "errors": []
        /// },
        /// "id": 1
        /// }
        /// ```
        ParseProgram: *const fn (userdata: *UserDataType, request: ParseProgramArgs) ErrorSet!ParseProgramResult,
        /// Parse KCL single file to Module AST JSON string with import dependencies
        /// and parse errors.
        ///
        /// # Examples
        ///
        /// ```jsonrpc
        /// Request
        /// {
        /// "jsonrpc": "2.0",
        /// "method": "ParseFile",
        /// "params": {
        /// "path": "./src/testdata/parse/main.k"
        /// },
        /// "id": 1
        /// }
        ///
        /// Response
        /// {
        /// "jsonrpc": "2.0",
        /// "result": {
        /// "ast_json": "{...}",
        /// "deps": ["./dep1", "./dep2"],
        /// "errors": []
        /// },
        /// "id": 1
        /// }
        /// ```
        ParseFile: *const fn (userdata: *UserDataType, request: ParseFileArgs) ErrorSet!ParseFileResult,
        /// load_package provides users with the ability to parse kcl program and semantic model
        /// information including symbols, types, definitions, etc.
        ///
        /// # Examples
        ///
        /// ```jsonrpc
        /// Request
        /// {
        /// "jsonrpc": "2.0",
        /// "method": "LoadPackage",
        /// "params": {
        /// "parse_args": {
        /// "paths": ["./src/testdata/parse/main.k"]
        /// },
        /// "resolve_ast": true
        /// },
        /// "id": 1
        /// }
        ///
        /// Response
        /// {
        /// "jsonrpc": "2.0",
        /// "result": {
        /// "program": "{...}",
        /// "paths": ["./src/testdata/parse/main.k"],
        /// "parse_errors": [],
        /// "type_errors": [],
        /// "symbols": { ... },
        /// "scopes": { ... },
        /// "node_symbol_map": { ... },
        /// "symbol_node_map": { ... },
        /// "fully_qualified_name_map": { ... },
        /// "pkg_scope_map": { ... }
        /// },
        /// "id": 1
        /// }
        /// ```
        LoadPackage: *const fn (userdata: *UserDataType, request: LoadPackageArgs) ErrorSet!LoadPackageResult,
        /// list_options provides users with the ability to parse kcl program and get all option information.
        ///
        /// # Examples
        ///
        /// ```jsonrpc
        /// Request
        /// {
        /// "jsonrpc": "2.0",
        /// "method": "ListOptions",
        /// "params": {
        /// "paths": ["./src/testdata/option/main.k"]
        /// },
        /// "id": 1
        /// }
        ///
        /// Response
        /// {
        /// "jsonrpc": "2.0",
        /// "result": {
        /// "options": [
        /// { "name": "option1", "type": "str", "required": true, "default_value": "", "help": "option 1 help" },
        /// { "name": "option2", "type": "int", "required": false, "default_value": "0", "help": "option 2 help" },
        /// { "name": "option3", "type": "bool", "required": false, "default_value": "false", "help": "option 3 help" }
        /// ]
        /// },
        /// "id": 1
        /// }
        /// ```
        ListOptions: *const fn (userdata: *UserDataType, request: ParseProgramArgs) ErrorSet!ListOptionsResult,
        /// list_variables provides users with the ability to parse kcl program and get all variables by specs.
        ///
        /// # Examples
        ///
        /// ```jsonrpc
        /// Request
        /// {
        /// "jsonrpc": "2.0",
        /// "method": "ListVariables",
        /// "params": {
        /// "files": ["./src/testdata/variables/main.k"],
        /// "specs": ["a"]
        /// },
        /// "id": 1
        /// }
        ///
        /// Response
        /// {
        /// "jsonrpc": "2.0",
        /// "result": {
        /// "variables": {
        /// "a": {
        /// "variables": [
        /// { "value": "1", "type_name": "int", "op_sym": "", "list_items": [], "dict_entries": [] }
        /// ]
        /// }
        /// },
        /// "unsupported_codes": [],
        /// "parse_errors": []
        /// },
        /// "id": 1
        /// }
        /// ```
