        /// Execute KCL file with args. **Note that it is not thread safe.**
        ///
        /// # Examples
        ///
        /// ```jsonrpc
        /// Request
        /// {
        /// "jsonrpc": "2.0",
        /// "method": "ExecProgram",
        /// "params": {
        /// "work_dir": "./src/testdata",
        /// "k_filename_list": ["test.k"]
        /// },
        /// "id": 1
        /// }
        ///
        /// Response
        /// {
        /// "jsonrpc": "2.0",
        /// "result": {
        /// "json_result": "{\"alice\": {\"age\": 18}}",
        /// "yaml_result": "alice:\n  age: 18",
        /// "log_message": "",
        /// "err_message": ""
        /// },
        /// "id": 1
        /// }
        ///
        /// Request with code
        /// {
        /// "jsonrpc": "2.0",
        /// "method": "ExecProgram",
        /// "params": {
        /// "k_filename_list": ["file.k"],
        /// "k_code_list": ["alice = {age = 18}"]
        /// },
        /// "id": 2
        /// }
        ///
        /// Response
        /// {
        /// "jsonrpc": "2.0",
        /// "result": {
        /// "json_result": "{\"alice\": {\"age\": 18}}",
        /// "yaml_result": "alice:\n  age: 18",
        /// "log_message": "",
        /// "err_message": ""
        /// },
        /// "id": 2
        /// }
        ///
        /// Error case - cannot find file
        /// {
        /// "jsonrpc": "2.0",
        /// "method": "ExecProgram",
        /// "params": {
        /// "k_filename_list": ["invalid_file.k"]
        /// },
        /// "id": 3
        /// }
