        /// "jsonrpc": "2.0",
        /// "method": "ExecProgram",
        /// "params": {
        /// "k_filename_list": []
        /// },
        /// "id": 4
        /// }
        ///
        /// Error Response
        /// {
        /// "jsonrpc": "2.0",
        /// "error": {
